def pow_root_pandigit(val, n, k):
    def is_pandigital(num):
        s = str(num)
        return len(s) == len(set(s)) and '0' not in s

    result = []
    i = int(val ** (1/n)) + 1
    while len(result) < k:
        candidate = i ** n
        if candidate <= val:
            i += 1
            continue
        root = i
        if is_pandigital(root) and is_pandigital(candidate):
            result.append([root, candidate])
        i += 1
    return result if len(result) > 1 else result[0]

