def findMedianSortedArrays(nums1, nums2):
    total_len = len(nums1) + len(nums2)
    half_len = total_len // 2
    i = j = 0
    prev = curr = None
    for _ in range(half_len + 1):
        prev = curr
        if i < len(nums1) and j < len(nums2):
            if nums1[i] <= nums2[j]:
                curr = nums1[i]
                i += 1
            else:
                curr = nums2[j]
                j += 1
        elif i < len(nums1):
            curr = nums1[i]
            i += 1
        else:
            curr = nums2[j]
            j += 1
    return (prev + curr) / 2 if total_len % 2 == 0 else curr

