class Solution:
    def canPlaceFlowers(self, flowerbed: list, n: int) -> bool:
        if not flowerbed:
            return n == 0

        count = 0
        length = len(flowerbed)

        if length == 1:
            return flowerbed[0] == 0 or n <= 1

        for i in range(length):
            if i == 0:
                if flowerbed[i] == 0 and flowerbed[i + 1] == 0:
                    flowerbed[i] = 1
                    count += 1
            elif i == length - 1:
                if flowerbed[i] == 0 and flowerbed[i - 1] == 0:
                    flowerbed[i] = 1
                    count += 1
            else:
                if flowerbed[i] == 0 and flowerbed[i - 1] == 0 and flowerbed[i + 1] == 0:
                    flowerbed[i] = 1
                    count += 1

        return count >= n

