        return f'<{tag_name} />'

    attrs = []
    if 'cls' in kwargs:
        attrs.append(f'class="{kwargs["cls"]}"')
    for key, value in kwargs.items():
        if key != 'cls':
            attrs.append(f'{key.replace("_", "-")}="{value}"')

    attr_str = ' '.join(attrs)
    content = '\n'.join(args)

    return f'<{tag_name} {attr_str}>{content}</{tag_name}>'

